DO $$
DECLARE
    staged_count INTEGER;
    missing_customer_count INTEGER;
    missing_sku_count INTEGER;
    mismatch_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO staged_count FROM inventory_import_stage;
    IF staged_count <> 500 THEN
        RAISE EXCEPTION 'Expected 500 staged rows; found %', staged_count;
    END IF;

    SELECT COUNT(*)
    INTO missing_customer_count
    FROM (SELECT DISTINCT customer_name FROM inventory_import_stage) AS stage
    LEFT JOIN customers USING (customer_name)
    WHERE customers.customer_id IS NULL;

    IF missing_customer_count <> 0 THEN
        RAISE EXCEPTION 'The FairPrice customer row is missing. Run migration 002 first.';
    END IF;

    SELECT COUNT(*)
    INTO missing_sku_count
    FROM (SELECT DISTINCT sku FROM inventory_import_stage) AS stage
    LEFT JOIN skus USING (sku)
    WHERE skus.sku IS NULL;

    IF missing_sku_count <> 0 THEN
        RAISE EXCEPTION '% mapped SKU(s) are missing from public.skus.', missing_sku_count;
    END IF;

    SELECT COUNT(*)
    INTO mismatch_count
    FROM (
        SELECT
            expected.period_start,
            expected.metric_name,
            expected.expected_value,
            COALESCE(SUM(stage.metric_value), 0) AS staged_value
        FROM inventory_expected_totals AS expected
        LEFT JOIN inventory_import_stage AS stage
          ON stage.period_start = expected.period_start
         AND stage.metric_name = expected.metric_name
        GROUP BY
            expected.period_start,
            expected.metric_name,
            expected.expected_value
        HAVING ABS(COALESCE(SUM(stage.metric_value), 0) - expected.expected_value) > 0.00000001
    ) AS mismatches;

    IF mismatch_count <> 0 THEN
        RAISE EXCEPTION '% monthly reconciliation check(s) failed.', mismatch_count;
    END IF;
END;
$$;

INSERT INTO inventory_metrics (
    customer_id,
    sku,
    period_start,
    period_end,
    metric_name,
    metric_value,
    value_type,
    as_of_date,
    source_file,
    source_sheet,
    source_cell,
    source_formula,
    data_source
)
SELECT
    customer.customer_id,
    stage.sku,
    stage.period_start,
    stage.period_end,
    stage.metric_name,
    stage.metric_value,
    stage.value_type,
    stage.as_of_date,
    stage.source_file,
    stage.source_sheet,
    stage.source_cell,
    stage.source_formula,
    stage.data_source
FROM inventory_import_stage AS stage
JOIN customers AS customer USING (customer_name)
ON CONFLICT (
    customer_id,
    sku,
    period_start,
    metric_name,
    value_type,
    as_of_date,
    data_source
)
DO UPDATE SET
    period_end = EXCLUDED.period_end,
    metric_value = EXCLUDED.metric_value,
    source_file = EXCLUDED.source_file,
    source_sheet = EXCLUDED.source_sheet,
    source_cell = EXCLUDED.source_cell,
    source_formula = EXCLUDED.source_formula,
    loaded_at = CURRENT_TIMESTAMP;

DO $$
DECLARE
    stored_count INTEGER;
BEGIN
    SELECT COUNT(*)
    INTO stored_count
    FROM inventory_metrics AS metric
    JOIN customers AS customer USING (customer_id)
    WHERE customer.customer_name = 'fairprice'
      AND metric.as_of_date = DATE '2026-07-31'
      AND metric.data_source = 'inventory_workbook'
      AND metric.source_file = 'P&L_Forecast_Revised_2026_updated_Aug_onwards_SI,_July_SOxlsx.xlsx'
      AND metric.period_start BETWEEN DATE '2025-01-01' AND DATE '2026-07-01';

    IF stored_count <> 500 THEN
        RAISE EXCEPTION 'Expected 500 stored rows after upsert; found %', stored_count;
    END IF;
END;
$$;

-- Review these result sets in Cloud SQL Studio before considering the import complete.
SELECT
    COUNT(*) AS stored_rows,
    MIN(metric.period_start) AS first_period,
    MAX(metric.period_start) AS last_period,
    COUNT(DISTINCT metric.sku) AS sku_count
FROM inventory_metrics AS metric
JOIN customers AS customer USING (customer_id)
WHERE customer.customer_name = 'fairprice'
  AND metric.as_of_date = DATE '2026-07-31'
  AND metric.data_source = 'inventory_workbook'
  AND metric.source_file = 'P&L_Forecast_Revised_2026_updated_Aug_onwards_SI,_July_SOxlsx.xlsx';

SELECT
    metric.period_start,
    metric.metric_name,
    SUM(metric.metric_value) AS stored_total
FROM inventory_metrics AS metric
JOIN customers AS customer USING (customer_id)
WHERE customer.customer_name = 'fairprice'
  AND metric.as_of_date = DATE '2026-07-31'
  AND metric.data_source = 'inventory_workbook'
  AND metric.source_file = 'P&L_Forecast_Revised_2026_updated_Aug_onwards_SI,_July_SOxlsx.xlsx'
  AND metric.period_start IN (DATE '2026-01-01', DATE '2026-02-01')
GROUP BY metric.period_start, metric.metric_name
ORDER BY metric.period_start, metric.metric_name;

COMMIT;
